import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.BF53ZjCA.js";const h=JSON.parse('{"title":"Identification","description":"","frontmatter":{"title":"Identification"},"headers":[],"relativePath":"identification/intro.md","filePath":"identification/intro.md","lastUpdated":1790876393000}'),r={name:"identification/intro.md"};function s(o,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="identification" tabindex="-1">Identification <a class="header-anchor" href="#identification" aria-label="Permalink to &quot;Identification&quot;">​</a></h1><p>Identification uses recorded, reproducible physical and optical evidence to narrow a material candidate. This module supports observation, basic screening, and evidence documentation; it does not turn appearance or one reading into a certain answer. Follow this path: record the sample and scope, start with low-risk observation, escalate physical and optical tests by risk, distinguish “supports a candidate”, “consistent with a candidate”, and “cannot exclude”, then refer to a lab when needed.</p><p><strong>What this module can do:</strong> teach observation, test-condition logging, and the role of RI / SG / optical observations in an evidence chain, producing an educational screening record.</p><p><strong>What it cannot do:</strong> a photo, appearance, single reading, or Assist response cannot establish a specific sample&#39;s natural/synthetic identity, treatment, origin, grade, or value. Preserve raw records and refer high-value, insurance, origin, or disclosure decisions to a qualified laboratory.</p><h2 id="identification-topics" tabindex="-1">Identification Topics <a class="header-anchor" href="#identification-topics" aria-label="Permalink to &quot;Identification Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Summary</th></tr></thead><tbody><tr><td><a href="./identification-workflow.html">Identification Workflow &amp; Documentation</a></td><td>Professional identification is not a search for one “magic reading”; it is a reproducible chain of evidence. Record the sample first, begin with low-risk observations, combine physical, optical, and inclusion clues, then state the confidence limits, treatment disclosure, and whether a laboratory report is needed.</td></tr><tr><td><a href="./physical-tests.html">Physical Tests</a></td><td>Refractive index, specific gravity, hardness, and cleavage are the most basic identification tools — influenced by chemistry and crystal structure, so each species tends to fall within a comparable range; conditions, orientation, treatment, and sample state can shift the reading.</td></tr><tr><td><a href="./optical-tests.html">Optical Tests</a></td><td>Birefringence (polariscope), pleochroism (dichroscope), and UV fluorescence (UV lamp) provide optical and material clues — useful for screening species and deciding what to test next.</td></tr><tr><td><a href="./synthetic-and-imitation.html">Synthetics &amp; Imitations</a></td><td>Record at least four separate dimensions: natural or laboratory-grown, treated or not, a different-material imitation, and any doublet/triplet or composite structure. Synthetics, imitations, treated materials, and composites require different evidence paths; typical clues support candidates but do not replace laboratory disclosure.</td></tr><tr><td><a href="./same-color-gems.html">Same-Colour Gems</a></td><td>One colour can hide many species — red may be ruby, spinel, garnet, or glass. Combining RI / SG / pleochroism / inclusions narrows the candidate set, but overlap and unresolved results are normal. The red case is expanded alongside minimal blue and green educational branches; none is a complete decision tree for every material.</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA: Analysis of Gemstones at GIA Laboratories</a><span>Standard gemological testing, laboratory workflow, and laboratory-grown diamond analysis examples</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA: Analytical Methods Used in Geographic Origin Determination</a><span>RI/SG as an identification starting point and further analysis for origin opinions</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA: Infrared Spectroscopy and Its Use in Gemology</a><span>Spectroscopy and its relationship to atomic structure and natural/synthetic/treatment clues</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Ruby</a><span>Typical ruby RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Sapphire</a><span>Typical sapphire RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Emerald</a><span>Typical emerald RI, birefringence, specific gravity, hardness, and treatment/synthetic/imitation context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Spinel</a><span>Typical spinel RI, isotropy, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Diamond</a><span>Typical diamond RI, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Zircon</a><span>Typical zircon RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA: Iolite Description</a><span>Iolite pleochroism and viewing-direction context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA: Tanzanite Description</a><span>Tanzanite pleochroism, orientation, lighting, and heat-treatment context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Peridot</a><span>Typical peridot RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ: Tsavorite and Demantoid</a><span>Green garnet colour overlap and mineral distinction context</span><small>Open source ↗</small></li></ul></aside>',7)])])}const f=a(r,[["render",s]]);export{h as __pageData,f as default};
